+      border: 1px solid rgba(255, 255, 255, 0.72);
+      border-radius: 28px;
+      box-shadow: var(--shadow);
+      backdrop-filter: blur(18px);
+      padding: clamp(1.5rem, 4vw, 2.5rem);
+    }
+
+    .eyebrow {
+      color: var(--primary);
+      font-size: 0.8rem;
+      font-weight: 700;
+      letter-spacing: 0.12em;
+      margin: 0 0 0.75rem;
+      text-transform: uppercase;
+    }
+
+    h1 {
+      font-size: clamp(2rem, 6vw, 3.25rem);
+      line-height: 1;
+      letter-spacing: -0.06em;
+      margin: 0;
+    }
+
+    .lede {
+      color: var(--muted);
+      font-size: 1rem;
+      line-height: 1.6;
+      margin: 1rem 0 2rem;
+    }
+
+    .form-field {
+      border: 0;
+      margin: 0;
+      padding: 0;
+    }
+
+    .question-label {
+      display: block;
+      font-size: 1.05rem;
+      font-weight: 750;
+      margin-bottom: 1rem;
+    }
+
+    .radio-group {
+      display: grid;
+      gap: 0.8rem;
+    }
+
+    .radio-option {
+      align-items: center;
+      background: #fff;
+      border: 1px solid var(--border);
+      border-radius: 18px;
+      cursor: pointer;
+      display: flex;
+      gap: 0.9rem;
+      padding: 1rem;
+      transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
+    }
+
+    .radio-option:hover {
+      border-color: rgba(79, 70, 229, 0.45);
+      box-shadow: 0 12px 30px rgba(79, 70, 229, 0.08);
+      transform: translateY(-1px);
+    }
+
+    .radio-option input {
+      accent-color: var(--primary);
+      height: 1.1rem;
+      width: 1.1rem;
+    }
+
+    .radio-option:has(input:checked) {
+      border-color: var(--primary);
+      box-shadow: 0 0 0 4px var(--ring);
+    }
+
+    .option-copy {
+      display: grid;
+      gap: 0.15rem;
+    }
+
+    .option-title {
+      font-weight: 700;
+    }
+
+    .option-note {
+      color: var(--muted);
+      font-size: 0.9rem;
+    }
+
+    .submit-button {
+      appearance: none;
+      background: var(--primary);
+      border: 0;
+      border-radius: 999px;
+      box-shadow: 0 12px 30px rgba(79, 70, 229, 0.28);
+      color: #fff;
+      cursor: pointer;
+      font-size: 1rem;
+      font-weight: 750;
+      margin-top: 1.6rem;
+      padding: 0.95rem 1.35rem;
+      transition: background 160ms ease, box-shadow 160ms ease, transform 160ms ease;
+      width: 100%;
+    }
+
+    .submit-button:hover {
+      background: var(--primary-dark);
+      box-shadow: 0 16px 36px rgba(79, 70, 229, 0.32);
+      transform: translateY(-1px);
+    }
+
+    .submit-button:focus-visible,
+    .radio-option input:focus-visible {
+      outline: 3px solid var(--ring);
+      outline-offset: 3px;
+    }
+
+    .status-message {
+      color: var(--primary-dark);
+      font-weight: 650;
+      min-height: 1.4rem;
+      margin: 1rem 0 0;
+      text-align: center;
+    }
+  </style>
+</head>
+<body>
+  <main id="root" class="app-shell"></main>
+
+  <script>
+    const notificationOptions = [
+      {
+        value: "email",
+        label: "Email",
+        note: "Get updates delivered to your inbox."
+      },
+      {
+        value: "sms",
+        label: "SMS",
+        note: "Receive concise alerts by text message."
+      },
+      {
+        value: "push-notifications",
+        label: "Push Notifications",
+        note: "See timely updates on your device."
+      }
+    ];
+
+    function RadioOption({ value, label, note }) {
+      return `
+        <label class="radio-option">
+          <input type="radio" name="notificationPreference" value="${value}" required>
+          <span class="option-copy">
+            <span class="option-title">${label}</span>
+            <span class="option-note">${note}</span>
+          </span>
+        </label>
+      `;
+    }
+
+    function NotificationPreferenceForm() {
+      return `
+        <section class="form-card" aria-labelledby="page-title">
+          <p class="eyebrow">Preferences</p>
+          <h1 id="page-title">Stay in the loop</h1>
+          <p class="lede">Choose the channel that works best for product updates, account notices, and important reminders.</p>
+
+          <form id="notification-form">
+            <div class="form-field">
+              <span class="question-label">How do you prefer to receive notifications?</span>
+              <div class="radio-group" role="radiogroup" aria-labelledby="notification-question">
+                <span id="notification-question" hidden>How do you prefer to receive notifications?</span>
+                ${notificationOptions.map(RadioOption).join("")}
+              </div>
+            </div>
+
+            <button class="submit-button" type="submit">Save preference</button>
+            <p class="status-message" id="status-message" aria-live="polite"></p>
+          </form>
+        </section>
+      `;
+    }
+
+    function App() {
+      return NotificationPreferenceForm();
+    }
+
+    document.getElementById("root").innerHTML = App();
+
+    document.getElementById("notification-form").addEventListener("submit", (event) => {
+      event.preventDefault();
+      const formData = new FormData(event.currentTarget);
+      const selectedValue = formData.get("notificationPreference");
+      const selectedOption = notificationOptions.find((option) => option.value === selectedValue);
+      document.getElementById("status-message").textContent = `Preference saved: ${selectedOption.label}`;
+    });
+  </script>
+</body>
+</html>
*** End Patch
